import sys
P=[l.split(';')[0].split() for l in open('prog.pw9')]
P=[p for p in P if p]
r=dict(a=0,b=0,c=0,d=0)
v=lambda x:r[x] if x in r else int(x)
pc=0;n=0;s=0
while 0<=pc<len(P):
    i=P[pc];o=i[0];n+=1;pc+=1
    if o=='set':r[i[1]]=v(i[2])%65536
    elif o=='add':r[i[1]]=(r[i[1]]+v(i[2]))%65536
    elif o=='mul':r[i[1]]=(r[i[1]]*v(i[2]))%65536
    elif o=='mod':
        if v(i[2])>0:r[i[1]]%=v(i[2])
    elif o=='dec':r[i[1]]=max(0,r[i[1]]-1)
    elif o=='jnz':
        if v(i[1])!=0:pc+=v(i[2])-1
    elif o=='skp':
        if v(i[1])<v(i[2]):pc+=1
    elif o=='out':s+=v(i[1])
print(s,n)
E
python3 -I /tmp/sim.py > /dev/null; python3 /tmp/sim.py | tee answer.txt
